// Builds src/components/blocks/Global/globe/landMask.data.ts: a 1-bit land/sea mask of the Earth for the dot globe.
//
// Why: the globe is made of dots placed on land only. Instead of shipping a map file, the land of Natural Earth 110m
// (public domain, package `world-atlas`) is rasterized once into a 360 x 180 grid (1 cell = 1 degree, 8 KB as base64).
// At runtime the globe puts its dots on an even sphere lattice and keeps those that fall on land cells.
//
// Run: node scripts/build-globe-land.mjs   (the output is generated, do not edit it by hand)
import { readFileSync, writeFileSync } from 'node:fs'
import { geoContains } from 'd3-geo'
import { feature } from 'topojson-client'

const WIDTH = 360
const HEIGHT = 180

const topology = JSON.parse(readFileSync('node_modules/world-atlas/land-110m.json', 'utf8'))
const land = feature(topology, topology.objects.land)

// Row 0 is the north (lat 89.5), column 0 is the west (lon -179.5); the sample point is the center of the cell.
const bytes = new Uint8Array(Math.ceil((WIDTH * HEIGHT) / 8))
let landCells = 0
for (let row = 0; row < HEIGHT; row++) {
  for (let column = 0; column < WIDTH; column++) {
    const longitude = column - 180 + 0.5
    const latitude = 90 - row - 0.5
    if (geoContains(land, [longitude, latitude])) {
      const index = row * WIDTH + column
      bytes[index >> 3] |= 1 << (index & 7)
      landCells++
    }
  }
}

const source = `// Generated by scripts/build-globe-land.mjs from Natural Earth 110m land. Do not edit by hand.
// ${WIDTH} x ${HEIGHT} cells of 1 degree, row 0 = north, column 0 = west, one bit per cell (bit 0 first).
export const LAND_MASK_WIDTH = ${WIDTH}
export const LAND_MASK_HEIGHT = ${HEIGHT}
export const LAND_MASK_BASE64 = '${Buffer.from(bytes).toString('base64')}'
`
writeFileSync('src/components/blocks/Global/globe/landMask.data.ts', source)
console.log(`land cells: ${landCells} of ${WIDTH * HEIGHT} (${((landCells / (WIDTH * HEIGHT)) * 100).toFixed(1)} %)`)
